import{_ as l,a0 as o,w as d,s as r,I as a,x as e,a1 as i,A as t,ao as p}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const y=JSON.parse('{"title":"如何组织构建多文件 C 语言程序（一） | LCTT x X-CMD","titleTemplate":false,"description":"如何组织构建多文件 C 语言程序（一） | LCTT (202002) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何组织构建多文件 C 语言程序（一） | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何组织构建多文件 C 语言程序（一） | LCTT (202002) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202002/20190729 How to structure a multi-file C program- Part 1","title":"如何组织构建多文件 C 语言程序（一）","tag":"202002","desc":""},"relativePath":"202002/20190729 How to structure a multi-file C program- Part 1.md","filePath":"[post].md"}'),c={name:"202002/20190729 How to structure a multi-file C program- Part 1.md"};function u(g,s,m,h,k,b){const n=o("Link");return d(),r("div",null,[s[35]||(s[35]=a("h1",{id:"如何组织构建多文件-c-语言程序-一",tabindex:"-1"},[e("如何组织构建多文件 C 语言程序（一） "),a("a",{class:"header-anchor",href:"#如何组织构建多文件-c-语言程序-一","aria-label":"Permalink to “如何组织构建多文件 C 语言程序（一）”"},"​")],-1)),s[36]||(s[36]=a("blockquote",null,[a("p",null,"准备好你喜欢的饮料、编辑器和编译器，放一些音乐，然后开始构建一个由多个文件组成的 C 语言程序。")],-1)),s[37]||(s[37]=a("p",null,[a("img",{src:"https://img.linux.net.cn/data/attachment/album/202002/26/214517o5p7q45l2a8jkx4k.jpg",alt:""})],-1)),s[38]||(s[38]=a("p",null,"大家常说计算机编程的艺术部分是处理复杂性，部分是命名某些事物。此外，我认为“有时需要添加绘图”是在很大程度上是正确的。",-1)),a("p",null,[s[1]||(s[1]=e("在这篇文章里，我会编写一个小型 C 程序，命名一些东西，同时处理一些复杂性。该程序的结构大致基于我在 《",-1)),i(n,{href:"https://linux.cn/article-10949-1.html"},{default:t(()=>[...s[0]||(s[0]=[e("如何写一个好的 C 语言 main 函数",-1)])]),_:1}),s[2]||(s[2]=e("》 文中讨论的。但是，这次做一些不同的事。准备好你喜欢的饮料、编辑器和编译器，放一些音乐，让我们一起编写一个有趣的 C 语言程序。",-1))]),s[39]||(s[39]=a("h3",{id:"优秀-unix-程序哲学",tabindex:"-1"},[e("优秀 Unix 程序哲学 "),a("a",{class:"header-anchor",href:"#优秀-unix-程序哲学","aria-label":"Permalink to “优秀 Unix 程序哲学”"},"​")],-1)),a("p",null,[s[5]||(s[5]=e("首先，你要知道这个 C 程序是一个 ",-1)),i(n,{href:"https://en.wikipedia.org/wiki/Unix"},{default:t(()=>[...s[3]||(s[3]=[e("Unix",-1)])]),_:1}),s[6]||(s[6]=e(" 命令行工具。这意味着它运行在（或者可被移植到）那些提供 Unix C 运行环境的操作系统中。当贝尔实验室发明 Unix 后，它从一开始便充满了",-1)),i(n,{href:"http://harmful.cat-v.org/cat-v/"},{default:t(()=>[...s[4]||(s[4]=[e("设计哲学",-1)])]),_:1}),s[7]||(s[7]=e("。用我自己的话来说就是：程序只做一件事，并做好它，并且对文件进行一些操作。虽然“只做一件事，并做好它”是有意义的，但是“对文件进行一些操作”的部分似乎有点儿不合适。",-1))]),s[40]||(s[40]=p('<p>事实证明，Unix 中抽象的 “文件” 非常强大。一个 Unix 文件是以文件结束符（EOF）标志为结尾的字节流。仅此而已。文件中任何其它结构均由应用程序所施加而非操作系统。操作系统提供了系统调用，使得程序能够对文件执行一套标准的操作：打开、读取、写入、寻址和关闭（还有其他，但说起来那就复杂了）。对于文件的标准化访问使得不同的程序共用相同的抽象，而且可以一同工作，即使它们是不同的人用不同语言编写的程序。</p><p>具有共享的文件接口使得构建<em>可组合的</em>的程序成为可能。一个程序的输出可以作为另一个程序的输入。Unix 家族的操作系统默认在执行程序时提供了三个文件：标准输入（<code>stdin</code>）、标准输出（<code>stdout</code>）和标准错误（<code>stderr</code>）。其中两个文件是只写的：<code>stdout</code> 和 <code>stderr</code>。而 <code>stdin</code> 是只读的。当我们在常见的 Shell 比如 Bash 中使用文件重定向时，可以看到其效果。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ls | grep foo | sed -e &#39;s/bar/baz/g&#39; &gt; ack</span></span></code></pre></div><p>这条指令可以被简要地描述为：<code>ls</code> 的结果被写入标准输出，它重定向到 <code>grep</code> 的标准输入，<code>grep</code> 的标准输出重定向到 <code>sed</code> 的标准输入，<code>sed</code> 的标准输出重定向到当前目录下文件名为 <code>ack</code> 的文件中。</p><p>我们希望我们的程序在这个灵活又出色的生态系统中运作良好，因此让我们编写一个可以读写文件的程序。</p><h3 id="喵呜喵呜-流编码器-解码器概念" tabindex="-1">喵呜喵呜：流编码器/解码器概念 <a class="header-anchor" href="#喵呜喵呜-流编码器-解码器概念" aria-label="Permalink to “喵呜喵呜：流编码器/解码器概念”">​</a></h3>',6)),a("p",null,[s[9]||(s[9]=e("当我还是一个露着豁牙的孩子懵懵懂懂地学习计算机科学时，学过很多编码方案。它们中的有些用于压缩文件，有些用于打包文件，另一些毫无用处因此显得十分愚蠢。列举最后这种情况的一个例子：",-1)),i(n,{href:"http://www.jabberwocky.com/software/moomooencode.html"},{default:t(()=>[...s[8]||(s[8]=[e("哞哞编码方案",-1)])]),_:1}),s[10]||(s[10]=e("。",-1))]),a("p",null,[s[12]||(s[12]=e("为了让我们的程序有个用途，我为它更新了一个 ",-1)),i(n,{href:"https://giphy.com/gifs/nyan-cat-sIIhZliB2McAo"},{default:t(()=>[...s[11]||(s[11]=[e("21 世纪",-1)])]),_:1}),s[13]||(s[13]=e(" 的概念，并且实现了一个名为“喵呜喵呜” 的编码方案的概念（毕竟网上大家都喜欢猫）。这里的基本的思路是获取文件并且使用文本 “meow” 对每个半字节（半个字节）进行编码。小写字母代表 0，大写字母代表 1。因为它会将 4 个比特替换为 32 个比特，因此会扩大文件的大小。没错，这毫无意义。但是想象一下人们看到经过这样编码后的惊讶表情。",-1))]),s[41]||(s[41]=p(`<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ cat /home/your_sibling/.super_secret_journal_of_my_innermost_thoughts</span></span>
<span class="line"><span>MeOWmeOWmeowMEoW...</span></span></code></pre></div><p>这非常棒。</p><h3 id="最终的实现" tabindex="-1">最终的实现 <a class="header-anchor" href="#最终的实现" aria-label="Permalink to “最终的实现”">​</a></h3>`,3)),a("p",null,[s[15]||(s[15]=e("完整的源代码可以在 ",-1)),i(n,{href:"https://github.com/JnyJny/meowmeow"},{default:t(()=>[...s[14]||(s[14]=[e("GitHub",-1)])]),_:1}),s[16]||(s[16]=e(" 上面找到，但是我会写下我在编写程序时的思考。目的是说明如何组织构建多文件 C 语言程序。",-1))]),s[42]||(s[42]=p(`<p>既然已经确定了要编写一个编码和解码“喵呜喵呜”格式的文件的程序时，我在 Shell 中执行了以下的命令 ：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ mkdir meowmeow</span></span>
<span class="line"><span>$ cd meowmeow</span></span>
<span class="line"><span>$ git init</span></span>
<span class="line"><span>$ touch Makefile     # 编译程序的方法</span></span>
<span class="line"><span>$ touch main.c       # 处理命令行选项</span></span>
<span class="line"><span>$ touch main.h       # “全局”常量和定义</span></span>
<span class="line"><span>$ touch mmencode.c   # 实现对喵呜喵呜文件的编码</span></span>
<span class="line"><span>$ touch mmencode.h   # 描述编码 API</span></span>
<span class="line"><span>$ touch mmdecode.c   # 实现对喵呜喵呜文件的解码</span></span>
<span class="line"><span>$ touch mmdecode.h   # 描述解码 API</span></span>
<span class="line"><span>$ touch table.h      # 定义编码查找表</span></span>
<span class="line"><span>$ touch .gitignore   # 这个文件中的文件名会被 git 忽略</span></span>
<span class="line"><span>$ git add .</span></span>
<span class="line"><span>$ git commit -m &quot;initial commit of empty files&quot;</span></span></code></pre></div><p>简单的说，我创建了一个目录，里面全是空文件，并且提交到 git。</p><p>即使这些文件中没有内容，你依旧可以从它的文件名推断每个文件的用途。为了避免万一你无法理解，我在每条 <code>touch</code> 命令后面进行了简单描述。</p><p>通常，程序从一个简单 <code>main.c</code> 文件开始，只有两三个解决问题的函数。然后程序员轻率地向自己的朋友或者老板展示了该程序，然后为了支持所有新的“功能”和“需求”，文件中的函数数量就迅速爆开了。“程序俱乐部”的第一条规则便是不要谈论“程序俱乐部”，第二条规则是尽量减少单个文件中的函数。</p><p>老实说，C 编译器并不关心程序中的所有函数是否都在一个文件中。但是我们并不是为计算机或编译器写程序，我们是为其他人（有时也包括我们）去写程序的。我知道这可能有些奇怪，但这就是事实。程序体现了计算机解决问题所采用的一组算法，当问题的参数发生了意料之外的变化时，保证人们可以理解它们是非常重要的。当在人们修改程序时，发现一个文件中有 2049 函数时他们会诅咒你的。</p><p>因此，优秀的程序员会将函数分隔开，将相似的函数分组到不同的文件中。这里我用了三个文件 <code>main.c</code>、<code>mmencode.c</code> 和 <code>mmdecode.c</code>。对于这样小的程序，也许看起来有些过头了。但是小的程序很难保证一直小下去，因此哥忒拓展做好计划是一个“好主意”。</p><p>但是那些 <code>.h</code> 文件呢？我会在后面解释一般的术语，简单地说，它们被称为头文件，同时它们可以包含 C 语言类型定义和 C 预处理指令。头文件中不应该包含任何函数。你可以认为头文件是提供了应用程序接口（API）的定义的一种 <code>.c</code> 文件，可以供其它 <code>.c</code> 文件使用。</p><h3 id="但是-makefile-是什么呢" tabindex="-1">但是 Makefile 是什么呢？ <a class="header-anchor" href="#但是-makefile-是什么呢" aria-label="Permalink to “但是 Makefile 是什么呢？”">​</a></h3><p>我知道下一个轰动一时的应用都是你们这些好孩子们用 “终极代码粉碎者 3000” 集成开发环境来编写的，而构建项目是用 Ctrl-Meta-Shift-Alt-Super-B 等一系列复杂的按键混搭出来的。但是如今（也就是今天），使用 <code>Makefile</code> 文件可以在构建 C 程序时帮助做很多有用的工作。<code>Makefile</code> 是一个包含如何处理文件的方式的文本文件，程序员可以使用其自动地从源代码构建二进制程序（以及其它东西！）</p><p>以下面这个小东西为例：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>00 # Makefile</span></span>
<span class="line"><span>01 TARGET= my_sweet_program</span></span>
<span class="line"><span>02 $(TARGET): main.c</span></span>
<span class="line"><span>03    cc -o my_sweet_program main.c</span></span></code></pre></div><p><code>#</code> 符号后面的文本是注释，例如 00 行。</p><p>01 行是一个变量赋值，将 <code>TARGET</code> 变量赋值为字符串 <code>my_sweet_program</code>。按照惯例，也是我的习惯，所有 <code>Makefile</code> 变量均使用大写字母并用下划线分隔单词。</p><p>02 行包含该<ruby>步骤<rt>recipe</rt></ruby>要创建的文件名和其依赖的文件。在本例中，构建<ruby>目标<rt>target</rt></ruby>是 <code>my_sweet_program</code>，其依赖是 <code>main.c</code>。</p><p>最后的 03 行使用了一个制表符号（<code>tab</code>）而不是四个空格。这是将要执行创建目标的命令。在本例中，我们使用 <ruby>C 编译器<rt>C compiler</rt></ruby>前端 <code>cc</code> 以编译链接为 <code>my_sweet_program</code>。</p><p>使用 <code>Makefile</code> 是非常简单的。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ make</span></span>
<span class="line"><span>cc -o my_sweet_program main.c</span></span>
<span class="line"><span>$ ls</span></span>
<span class="line"><span>Makefile  main.c  my_sweet_program</span></span></code></pre></div>`,18)),a("p",null,[s[18]||(s[18]=e("构建我们喵呜喵呜编码器/解码器的 ",-1)),i(n,{href:"https://github.com/JnyJny/meowmeow/blob/master/Makefile"},{default:t(()=>[...s[17]||(s[17]=[e("Makefile",-1)])]),_:1}),s[19]||(s[19]=e(" 比上面的例子要复杂，但其基本结构是相同的。我将在另一篇文章中将其分解为 Barney 风格。",-1))]),s[43]||(s[43]=p(`<h3 id="形式伴随着功能" tabindex="-1">形式伴随着功能 <a class="header-anchor" href="#形式伴随着功能" aria-label="Permalink to “形式伴随着功能”">​</a></h3><p>我的想法是程序从一个文件中读取、转换它，并将转换后的结果存储到另一个文件中。以下是我想象使用程序命令行交互时的情况：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ meow &lt; clear.txt &gt; clear.meow</span></span>
<span class="line"><span>$ unmeow &lt; clear.meow &gt; meow.tx</span></span>
<span class="line"><span>$ diff clear.txt meow.tx</span></span>
<span class="line"><span>$</span></span></code></pre></div><p>我们需要编写代码以进行命令行解析和处理输入/输出流。我们需要一个函数对流进行编码并将结果写到另一个流中。最后，我们需要一个函数对流进行解码并将结果写到另一个流中。等一下，我们在讨论如何写一个程序，但是在上面的例子中，我调用了两个指令：<code>meow</code> 和 <code>unmeow</code>？我知道你可能会认为这会导致越变越复杂。</p><h3 id="次要内容-argv-0-和-ln-指令" tabindex="-1">次要内容：argv[0] 和 ln 指令 <a class="header-anchor" href="#次要内容-argv-0-和-ln-指令" aria-label="Permalink to “次要内容：argv[0] 和 ln 指令”">​</a></h3><p>回想一下，C 语言 main 函数的结构如下：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>int main(int argc, char *argv[])</span></span></code></pre></div><p>其中 <code>argc</code> 是命令行参数的数量，<code>argv</code> 是字符指针（字符串）的列表。<code>argv[0]</code> 是包含正在执行的程序的文件路径。在 Unix 系统中许多互补功能的程序（比如：压缩和解压缩）看起来像两个命令，但事实上，它们是在文件系统中拥有两个名称的一个程序。这个技巧是通过使用 <code>ln</code> 命令创建文件系统链接来实现两个名称的。</p><p>在我笔记本电脑中 <code>/usr/bin</code> 的一个例子如下：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ls -li /usr/bin/git*</span></span>
<span class="line"><span>3376 -rwxr-xr-x. 113 root root     1.5M Aug 30  2018 /usr/bin/git</span></span>
<span class="line"><span>3376 -rwxr-xr-x. 113 root root     1.5M Aug 30  2018 /usr/bin/git-receive-pack</span></span>
<span class="line"><span>...</span></span></code></pre></div><p>这里 <code>git</code> 和 <code>git-receive-pack</code> 是同一个文件但是拥有不同的名字。我们说它们是相同的文件因为它们具有相同的 inode 值（第一列）。inode 是 Unix 文件系统的一个特点，对它的介绍超越了本文的内容范畴。</p><p>优秀或懒惰的程序可以通过 Unix 文件系统的这个特点达到写更少的代码但是交付双倍的程序。首先，我们编写一个基于其 <code>argv[0]</code> 的值而作出相应改变的程序，然后我们确保为导致该行为的名称创建链接。</p><p>在我们的 <code>Makefile</code> 中，<code>unmeow</code> 链接通过以下的方式来创建：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># Makefile</span></span>
<span class="line"><span>...</span></span>
<span class="line"><span>$(DECODER): $(ENCODER)</span></span>
<span class="line"><span>        $(LN) -f $&lt; $@</span></span>
<span class="line"><span>       ...</span></span></code></pre></div><p>我倾向于在 <code>Makefile</code> 中将所有内容参数化，很少使用 “裸” 字符串。我将所有的定义都放置在 <code>Makefile</code> 文件顶部，以便可以简单地找到并改变它们。当你尝试将程序移植到新的平台上时，需要将 <code>cc</code> 改变为某个 <code>cc</code> 时，这会很方便。</p><p>除了两个内置变量 <code>$@</code> 和 <code>$&lt;</code> 之外，该<ruby>步骤<rt>recipe</rt></ruby>看起来相对简单。第一个便是该步骤的目标的快捷方式，在本例中是 <code>$(DECODER)</code>（我能记得这个是因为 <code>@</code> 符号看起来像是一个目标）。第二个，<code>$&lt;</code> 是规则依赖项，在本例中，它解析为 <code>$(ENCODER)</code>。</p><p>事情肯定会变得复杂，但它还在管理之中。</p><hr>`,18)),a("p",null,[s[21]||(s[21]=e("via: ",-1)),i(n,{href:"https://opensource.com/article/19/7/structure-multi-file-c-part-1"},{default:t(()=>[...s[20]||(s[20]=[e("https://opensource.com/article/19/7/structure-multi-file-c-part-1",-1)])]),_:1})]),a("p",null,[s[26]||(s[26]=e("作者：",-1)),i(n,{href:"https://opensource.com/users/jnyjnyhttps://opensource.com/users/jnyjnyhttps://opensource.com/users/jim-salterhttps://opensource.com/users/cldxsolutions"},{default:t(()=>[...s[22]||(s[22]=[e("Erik O'Shaughnessy",-1)])]),_:1}),s[27]||(s[27]=e(" 选题：",-1)),i(n,{href:"https://github.com/lujun9972"},{default:t(()=>[...s[23]||(s[23]=[e("lujun9972",-1)])]),_:1}),s[28]||(s[28]=e(" 译者：",-1)),i(n,{href:"https://github.com/mengxinayan"},{default:t(()=>[...s[24]||(s[24]=[e("萌新阿岩",-1)])]),_:1}),s[29]||(s[29]=e(" 校对：",-1)),i(n,{href:"https://github.com/wxy"},{default:t(()=>[...s[25]||(s[25]=[e("wxy",-1)])]),_:1})]),a("p",null,[s[32]||(s[32]=e("本文由 ",-1)),i(n,{href:"https://github.com/LCTT/TranslateProject"},{default:t(()=>[...s[30]||(s[30]=[e("LCTT",-1)])]),_:1}),s[33]||(s[33]=e(" 原创编译，",-1)),i(n,{href:"https://linux.cn/"},{default:t(()=>[...s[31]||(s[31]=[e("Linux中国",-1)])]),_:1}),s[34]||(s[34]=e(" 荣誉推出",-1))])])}const x=l(c,[["render",u]]);export{y as __pageData,x as default};
